import json,hashlib
from pathlib import Path
p=Path(__file__).parent
all_s=[]
for c in sorted((p/'chunks').glob('chunk-*.json')): all_s+=json.loads(c.read_text())
sections=[]
def add(title,until,paras,examples=[],ed=[],pages=[],videos=[]):
 start=sections[-1]['end'] if sections else 0
 ss=[s for s in all_s if start<=s['start']<until]
 end=max([until]+[s['end'] for s in ss])
 fs=[{'source_type':'pdf_page','path':f'frames/page-{n:03d}.webp','source_label':'官方网页讲义截图汇编（非官方原生 PDF）','source_url':f'https://jyywiki.cn/GSE/2026/slides6.html#/{n}','page':n,'caption':cap} for n,cap in pages]
 fs +=[{'source_type':'video_frame','path':f'frames/video-{t}.webp','time':t,'caption':cap} for t,cap in videos]
 sections.append(dict(title=title,start=start,end=end,source_ids=[s['id'] for s in ss],paragraphs=paras,examples=examples,editor_notes=ed,frames=fs))
add('从意图到实现：错误会沿依赖传播',204.51,[
'本课接续上一讲的 Intent → Specification → Implementation：客户的意图需要变成明确规约，再成为实现。实现之后仍有维护阶段，因此不能把软件生命周期理解成“代码写完就结束”。需求认识、设计决定、模块、函数、测试都互相依赖，构成数据依赖图。',
'如果到实现阶段才发现某个需求或设计错误，修复会反向追到上游，再让依赖它的下游代码与测试失效。Royce 对简单瀑布式过程的批评，正是看到这种返工风险。软件工程因此既包括如何沟通、组织人和检查需求，也包括测试、分析等技术方法。',
'可追溯性（traceability）的理想是：每个测试用例或代码片段，都能追到它依据的设计或需求；修改一个设计时，可以知道哪些产物需要更新。UML 是试图用结构化、具有语义的共同语言对齐不同环节的尝试。'],pages=[(1,'回顾：Intent–Spec–Impl Gap、瀑布模型与 Data-Dependency Graph。')])
add('软件不软：微小偏差为什么能摧毁系统',363.20,[
'物理椅背受力后能回弹，软件却是遵从形式语义的逻辑制品。一个很小的表示错误可能完全改变执行过程，“能改代码”不等于“能轻松承受变化”。',
'讲师用硬件错误作极端例子：本来读入 N=1，若无符号整数高位被翻转，循环可能尝试读取巨大数量的数据，出现等待、内存错误或崩溃。随后提到数据中心处理器的静默错误，意在说明软件正确性还依赖运行环境的假设。',
'更常见的困难来自客户需求：软件既要有精确的逻辑，又要承接不断变化的业务世界。教务系统将作为本课贯穿案例。'],ed=['这些硬件现象是讲师的背景例证；本笔记没有独立审阅硬件错误研究，也不把“一位翻转必然使所有程序错误”当作严格定理。'],pages=[(2,'官方讲义：软件工程的基本观察——软件不软。')])
add('代码便宜以后，需求、产品与架构成为杠杆',593.74,[
'传统学生往往从语言与编码出发，逐步理解设计和需求；没有实现经验，很难判断一项要求的成本与可行性。但决定软件从零开始走向哪里的关键，通常发生在需求、产品和架构阶段。',
'讲师指出，这些问题难做统一的定量研究，研究中容易转向缺陷预测、代码分析等更易量化对象。这是课堂观点与调侃，不能理解为所有软件工程研究都没有实践价值。',
'当目标和边界足够清楚，AI 可以生成实现、测试、断言，多个 Agent 可以并行工作。讲师称自己在某些边界明确、验证方式清楚的任务上已经不逐行阅读实现。这里的前提是边界与 validation，并非对任意生成代码的无条件信任。'],pages=[(4,'Agentic AI：目标明确的代码生产便宜，需求、产品设计与架构影响后续软件生产。')])
add('MVP、早期决定与不断进入上下文的技术债',903.56,[
'MVP 选择最重要的功能，从意图到规约再到实现走通一个纵向切片。不要过早打磨依赖尚未稳定设计的细节：例如按钮样式依赖整体界面，界面又依赖功能安排，上游变化会让此前打磨被丢弃。',
'同一份功能需求，仅增加“CLI”或“client-server”等架构提示，就可能生成完全不同的项目：前者会引入命令行解析，后者会先考虑服务、数据库和存储。第一个文件一旦写入，就会进入 Agent 的后续上下文，影响以后每次修改。',
'早期决定未必错误，但会构成以后必须承接的约束。个人工具的命令行偏好、隐含知识与操作习惯，不能直接搬给普通用户；需求、产品设计和架构共同决定软件走向。',
'引言末尾有一次实际设备故障：系统界面和 OBS 推流仍在工作，鼠标键盘却不能使用。讲师转向日志诊断，并提醒生成软件若没有足够日志，故障后很难解释发生过什么；日志缺失也是会留下来的设计负担。'],ed=['视频原始章节标为“引言（后半音频翻车）”。现有转写仍覆盖这一段，但这不能证明每句听辨准确；未将讲义补充伪装为修复后的口述。音频诊断范围与限制详见本课 audit.json。'])
add('真实教务系统演示：需求远不止几张表',1400.35,[
'讲师登录现有教务系统，先试用隐藏的 AI 服务检索：询问教室灯具问题应联系谁，又问“我现在在上什么课”。后者返回教师课表入口，需要再进入本科教师身份查看课表；课堂没有证明 AI 已完整理解个人教学上下文。',
'随后依次浏览教学任务、教学周历、历史授课学期、期末考试签到表、教材编辑、大纲和助教等页面。每一个按钮都伴随条件：考试未发布时不能打印签到表；助教只能在维护时间内申请；多身份、多学期必须可选择并明确显示。',
'课堂出现教材编辑迟迟未响应、随后页面刷新，以及慕课助教列表显示异常等现象。这些是现场观察，未定位具体后端故障原因。教学班与慕课助教是需求逐年叠加的例子：一种新授课方式出现后，还会带来新角色和新管理规则。',
'真实交付同时面对功能与非功能要求，并且需要承担合同责任。看似能实现页面，不等于理解整个业务或承受长期维护。讲师关于“把预算换成 token 可能更便宜”的说法是课堂设想，没有成本核算支撑。'])
add('让 Agent 逆向整理需求：编号、证据与验收',1812.33,[
'讲师让 Agent 探索现有系统中教师相关功能，形成需求说明书。范围明确是教师端相关功能，不能把它当作全校所有业务的完整规格。说明书包含调研方法和证据边界、业务目标、成功标准、角色、用例规约、功能目录、验收场景、术语与配套材料。',
'一个需求点不只写一句自然语言，还通过稳定编号关联参与者和业务目标。这使“教学班与学生管理有关”成为可检查的关系，帮助实现 traceability。术语表则让客户与开发者在词义不清时有共同参照。',
'课堂逐项读到服务分类与检索、多种已分配身份下的身份选择、当前身份显示、学年学期或业务批次及授权范围内切换。它们看似繁琐，却决定功能到底有没有实现。',
'有结构的需求清单与验收场景可以分派给不同团队，并据此跟踪进度。讲师用计算机系统基础课程的 NEMU 文档类比：OJ 的简单输入输出，与模拟器、调试器、指令行为的长规格，复杂度不同，但都在训练理解和实现规约。'],videos=[(1540,'现场需求说明书：用编号关联需求与角色/目标；此图是 25:40 的原视频帧。')])
add('只凭需求生成原型：成功路径与验证边界',1971.22,[
'演示中的第二个 Agent 被要求不看原系统，仅根据需求说明书生成一个假的教务系统。讲师打开生成页面，查看教学任务、教材记录和学生名单，并编辑教材后保存。它与原系统在功能结构上相似，说明清晰规格能显著约束生成结果。',
'讲师先尝试输入 -1，界面不允许；再输入极大的正数，31:52画面弹出“Value must be less than or equal to 100.”，证明存在数值上限100。随后改成100，31:55学生列表显示“100次”和“缺课记录已更新”。100仍可能超过本学期全部课次，因此讲师说“他没有阻止我”指的是业务上不合理的次数仍可保存。',
'后面讲师说大数被拒绝，与画面并不矛盾：极大数被拒和100被保存是两个状态。逐帧核对后可区分“有一个通用数值上限”与“依据实际授课次数验证业务合理性”。画面证明了前端提示和保存结果，不能据此声称后端绕过测试、权限、并发和全部例外均已通过。'],videos=[(1912,'31:52 原视频：超大数被拒，浏览器显示必须小于或等于100。'),(1915,'31:55 原视频：改成100后保存成功。通用数值上限不等于符合本学期实际课次。')])
add('同理心与领域知识：需求为何永远不能一次说清',2179.88,[
'从入学到毕业的业务链，不只包含学生、课程与成绩，还包括权限、规则版本、数据同步与操作留痕。需求分析要不断和客户沟通，连“学期选择放哪里”“哪个位置有修改按钮”也需要对齐。',
'设计者不是用户本身。讲师以熟悉程序的年轻开发者和即将退休的教务人员作对照：后者可能更在意字体、按钮大小与少误点，而非最新数据库或最优性能。行业经验的价值，是知道学位授予流程和真实使用者如何工作。',
'实现第一版后，系统就背上了已有决定。客户难以一次列出所有条件，规则还会改变。课堂的真实引子是离散数学课程被拆成两门：旧培养方案、准出条件与保研要求怎样与新课程衔接，原来的单课程下拉框已经无法自然表达。'],pages=[(7,'官方讲义需求分解图：从入学到毕业的参与者、过程与支撑能力。'),(8,'需求泥潭：多方目标、规则和例外；讲义补充了利益冲突与裁决问题。')])
add('课程拆分、替代与人工豁免：局部变更穿透全系统',2451.83,[
'原始毕业要求可能只允许“增加一门必修课程”。课程拆分后，规则却需要表达旧课程或新课程组合的替代关系。增加一个“或”不是单纯修改下拉框：数据表示、审核算法、历史学生适用条件和相关界面都可能被影响。',
'再叠加转专业、交换、重修与抵扣，问题更复杂。另一个院系的一门离散数学，究竟抵新方案的一门还是两门？临近毕业的学生碰到课程只在另一个学期开设，不能等下一年，又该怎样处理？',
'现实常出现线下批准：教学负责人认为旧课程可以替代新要求，而系统没有表达能力，于是联系工程师直接把毕业条件改为满足。业务上可能有合理解释，系统里却只剩一个结果，解释与依据留在系统外。'],ed=['官方讲义第9页的 160 学分、40/72/28/20 分类、高数A或B+桥接、交换课合抵与绩点规则是明确标为虚构的示例，不是南京大学实际政策。课堂没有逐条口述这些数字，故以下作为讲义补充保留。','讲义补充：人工“视为满足”也应有需求——批准人、理由、适用学生、豁免项目与方案版本，而不是只有一个无来源的布尔值。'],pages=[(9,'讲义补充｜虚构培养方案案例。160 学分及各分类数字不可当作学校政策。')])
add('缺课次数 −1 与“没有银弹”',2669.56,[
'讲师回忆首次使用教师端系统时，绕过前端校验，把一位学生缺课次数从 0 改成 -1；随后所有能选出该学生选课记录的页面都返回 500。其后联系教务，次日恢复，但具体修复方式未知。',
'这个例子说明局部数据假设可能被系统多个地方依赖。它不证明具体错误必然来自某种数据库类型，也不证明只加前端限制就能解决。现场生成原型中的验证表现，与这段旧系统经历需要分开。',
'MVP 能快速暴露错误、降低早期推倒重做成本，但也会造成驾驭复杂系统的错觉。上线后系统必须承接现实业务、既有数据与历史决定，不能像课程项目那样随时清零。需求沿依赖图传播，持续变化使维护成本增长；“没有银弹”是没有一招彻底消灭这种复杂性。'],pages=[(10,'旧教务系统的 -1 案例：局部异常沿依赖传播。'),(12,'官方讲义：需求变更可以同时影响课程对应、学分、审核、成绩单与测试。')])
add('架构从小程序开始：把复杂性和变化隔开',3086.60,[
'架构要回答：最小的软件如何在未来膨胀和变化时仍有韧性？“先把所有需求塞进数据库”能很快跑起来，但如果概念之间没有合理分离，随后会陷入维护泥潭。架构并不只属于大系统。',
'最小的 main 也可以分为 read_input、parse_input、process_input、write_output。命令行的 argc/argv 包含长短参数和约定，用 getopt 解析后得到可供业务处理的状态，就是把字符串格式复杂性关在边界里的例子。',
'每个模块里都可以讨论 intent、specification 和 implementation。学习库函数与语言特性不应停在语法用法，而应继续问“为什么这样组织、它隔离了什么变化”。把复杂输入转换为明确中间状态，这个模式还会在二维码编译器里再次出现。'],ed=['讲义补充：仅切成四个函数不自动形成架构边界；仍需明确数据所有权、资源责任和依赖方向，避免共享全局状态把函数重新耦合起来。'],pages=[(15,'官方图示：复杂性有归处，变化有边界。'),(16,'小程序四阶段结构；数据如何穿过边界比函数数量更关键。')])
add('非递归汉诺塔：数学规律、任务栈与抽象机器',3478.61,[
'同一个非递归汉诺塔需求，能用完全不同的表示实现。讲师用几种模型与自己的实现对照；这些是课堂个案，没有统一模型评测设计，不能外推为模型普遍排名。',
'第一种用数学规律：第 step 步移动的盘号等于 1 加 step 二进制尾随零的个数，每个盘子的方向固定。复杂性被移到了规律及其证明中，代码很短，却需要理解这些不变量；总移动次数仍是 2^n−1。',
'第二种用任务栈：保存尚未完成的搬盘任务，每次弹出栈顶；n=1 直接移动，否则拆成三项任务。由于后进先出，压入顺序必须与期望执行顺序相反。这保留递归的任务结构，只把隐式调用栈改成显式数据。',
'第三种模拟抽象机器：每个栈帧保存 n、三根柱子角色与程序计数器 pc；调用压栈、返回出栈，以小步状态转移模拟 C 程序的操作语义。它对汉诺塔可能显得过重，却能推广到相互递归等更一般情形。',
'讲师还展示搜索得到的复杂代码作为反例。重点不是一味追求行数少，而是选择何种表示能让需求更清楚、更好推理。数学结构、任务分解和执行机器，分别把复杂性放在不同层次。'],examples=['整理者依据官方代码验证：n=3 时移动盘号为 1,2,1,3,1,2,1；对 n=1..10 模拟柱栈、检查每次合法性并与递归序列比较，全部一致。此为独立小算例检查，不是对原课堂完整代码工程的测试。'],ed=['官方讲义为 uint64_t 写法；完整讲义文字限定 1≤n<64，并要求足够的 position 数组。截取循环本身不是可直接编译的完整程序。'],pages=[(18,'数学规律方案：尾随零决定盘号，奇偶关系决定方向。'),(19,'任务栈方案：三次 push 采用执行顺序的反序。'),(20,'抽象机器方案：Frame、pc、call 与 ret 显式表示递归执行。'),(22,'同一个问题的不同表达：选择表示就是选择复杂性的位置。')])
add('Excel 二维码：明确需求也隐藏着演化风险',3885.93,[
'需求很明确：用户修改一个输入单元格，工作表公式重新生成可扫描二维码。但直接拼出大量公式，会把括号、引用、算法步骤与布局绑在一起；模型反复修括号只是表面症状。',
'版本兼容也是需求：只给自己用可以采用新函数，要发给安装旧版 Excel 的用户就要考虑旧功能。课堂以 VLOOKUP/XLOOKUP 类比功能演化，未精确确认发布时间，本笔记不把课堂口述年份当作软件版本事实。',
'把二维码整体移一格、增加输入、改变计算方法，都可能让硬编码公式大范围失效。两千行小程序可以重写，但它一旦嵌进更大系统，关联就使重做昂贵。好的架构应让这些变化分别有明确位置。'],pages=[(24,'官方讲义：长公式、版本兼容、布局移动与新增输入等变化。')])
add('中间表示：先正确表达计算，再生成目标公式',4268.37,[
'二维码可以用简洁的伪代码描述，困难在于把这种计算搬到 Excel。讲师现场让 Agent 写算法概述，展示版本、纠错等级、掩码、数据编码与纠错计算。课堂这一处口述细节不足以重建完整二维码标准，因此不将零散系数或码字数作为通用参数。',
'解法是在 Python 与 Excel 之间设计中间语言。比如异或、索引、字符串取值等运算成为表达式树节点；每个节点有清楚语义，并各有 Python 和 Excel 的翻译规则。',
'同一计算图先生成 Python 便于调试和验证，确认算法后再生成 Excel 交付。表达式树递归输出时，生成器统一处理子表达式、括号与单元格引用；算法不用逐处硬编码地址。',
'这与 getopt 的模式相同：先把复杂输入变成清楚的中间状态，再由后续步骤处理。架构的价值不是“多了一层”，而是把变化和错误定位到有责任边界的位置。'],ed=['课堂说“没有 Python 到 Excel 编译器”是这一案例的任务语境，不作为全世界工具不存在的断言。','讲义补充：生成时可用 Python 循环展开有限计算图；用户字符串应保留为符号输入，输入决定的分支须形成 Select 节点，留给运行时重算。若生成时直接固定输入，得到的只是一张固定二维码。','讲义补充：两个后端可能共享同一算法错误。除比较 Python 与 Excel 实际重算结果，还需用独立实现或解码器校验；逐像素比较前须固定版本、纠错等级、分段与掩码。'],pages=[(25,'讲义补充的关键边界：构图时与运行时，符号输入与 Select。'),(26,'一份中间语言，两种执行方式：调试验证与 Excel 交付。'),(28,'讲义补充：IR 类型/容量/编码语义与独立验证，避免两后端同错。')])
add('优化与变化：由中间层承接',4353.16,[
'中间语言可以承接优化规则：把重复且值不变的计算提到循环外，或按性能分析结果改变表达方式。先测瓶颈，再做 profiling-guided optimization，而不是凭代码看起来长就盲目改写。',
'Excel 版本变化时，可以替换对应算子的后端实现，而不从头重做整个二维码算法。这也是其他领域中算子与后端分离的共同思路。',
'讲义把责任进一步写清：版本兼容归目标能力与降级规则；布局移动归地址分配；算法变化归构图或优化；新增输入归输入绑定、拼接、编码与容量。明确的接口使一次变化主要落在负责它的模块中。'],ed=['讲义补充：常量折叠、公共子表达式共享、LET 或辅助单元格各有适用条件；须分别测首次完整计算、输入变化后的重算和工作簿体积。课堂未逐项演示这些优化。'],pages=[(27,'讲义补充：四类需求变化分别交给哪个模块。'),(29,'讲义补充：计算图优化与 Excel 实际成本，包含课堂未展开的具体策略。')])
add('大文件能运行，为什么还要重新审视架构',4651.29,[
'回到大型教务系统，讲师先看生成项目的大型 TSX 和 services 文件，再请另一个模型评价。模型识别出三层单体、前后端分离，以及乐观锁、幂等、事务审计、统一错误等设计；这些是现场模型评价，笔记没有完整审计该代码库。',
'讲师承认生成代码具备一些工程经验，但认为“能维护”和“适合长期业务演化”不是同一个判断。把逻辑挤在几个大文件里，后续新增功能可能越来越难预测。',
'CRUD 将软件理解为现实状态的投影：数据库保存学生、教师、院系和选课，业务操作把一个状态改成下一个状态。这个模型本身并非错误，需要进一步考察它保留了什么、丢掉了什么。'],pages=[(32,'官方讲义：生成原型能维护的判断带有限定——应拆分并统一规则。')],videos=[(4458,'74:18 原视频：现场查看生成项目的大型 TSX/services 文件；代码体积不是维护性的充分证据。')])
add('当前状态掩盖的事实、规则与决定',5044.72,[
'数据库规范化用标识符关联实体，减少同一信息多处重复带来的更新异常。例如学生改名，其他表引用稳定学号即可，不应靠重复姓名表示身份。',
'但消除字段冗余并不等于保留推理依据。“允许毕业”可能由学分、毕设、培养方案和人工审批计算得出。只保存 true/false，看到结果时无法知道为何成立，成绩或规则变化后也难以定位需要重审的结论。',
'现实世界还会领先于系统：政策已经批准，方案尚未导入；教室不能使用，系统仍按原计划排课；学生急需毕业，软件尚不能表达特例。人工修改当前状态能救急，却可能不断累积无法解释的数据。',
'需要区分历史事实、当时规则以及据此作出的正式决定。业务结论应保留输入与版本、审批依据和影响关系，否则让 AI 修当前报错，也补不回过去被丢弃的含义。'],pages=[(34,'当前状态混合了历史事实、规则和决定；字段不重复仍可能丢失计算依据。'),(35,'讲义补充：把人工例外表达成带批准人和理由的业务过程。')])
add('计算机系变学院：身份、属性与历史归属',5400.54,[
'若直接将旧 department 记录名称覆盖为“计算机学院”，历史毕业记录一经关联查询，也会显示新名称，与当年事实不符。若新建对象，现有学生、课程、权限仍指向旧对象，迁移关联又可能改写历史归属。',
'问题不是简单选“改名”或“新 ID”，而是判断业务身份是否延续，以及名称、层级和隶属关系在什么时间有效。当前结构下汇总，与查询当时归属，是两种不同口径。',
'代码可以重新生成，但历史依据不能凭空补回。测试环境里的干净数据迁移，与长期运行、混有人工救火数据的生产迁移，风险不同。讲师以过去研究生教务系统在扩招与培养类型变化中难以维护的经历，说明领域知识与持续维护经验的价值。'],ed=['讲义补充：身份延续时可保留稳定 org_id 并为属性保留有效期；产生新组织时创建新 ID、记录带日期的承继关系，同时保留原归属。培养方案应单独版本化，不能随名称变化自动更换。'],pages=[(37,'讲义补充：旧 ID 与新 ID 各自承诺的业务含义，以及按有效期建模的方案。'),(38,'代码可重写，历史不能凭空补出；这也是复杂 ERP 维护困难的来源。')])
add('事件溯源：保留事实，再按需要投影状态',5755.97,[
'讲师从可持久化数据结构引出另一种观察方式：不仅保存当前状态，也可以保留历史版本、操作或状态差量。课堂用树的路径复制说明结构共享，也提到日志与版本管理；重点是让过去的变化不再随更新消失。',
'若退学操作只是删除学生及关联，后来新增“复学”需求时，很难重建以前的事实。若退学等事件已经保存，就可以 replay 到相关历史状态，再据新业务逻辑处理复学。新功能的业务逻辑仍要写，保存历史不会自动替你完成需求。',
'院系调整同样可以成为带时间的事件：查询毕业时的归属使用当时历史，查询当前情况可以投影与该人相关的后续变化。Event Sourcing（事件溯源）就是从历史事件生成状态，而不只原地维护当前快照。',
'重放性能可以借助快照、缓存及增量更新控制。具体选择仍是 trade-off：既有系统迁到事件溯源很困难，提前保留足够历史则会为未来改变规则留下余地。'],ed=['整理者校正：数据库 journal、Git、可持久化树和业务事件不是同一种语义结构，不能认为有底层日志就自动完成事件溯源。需要保存被业务接受的事实及其必要依据。','讲义补充：事件格式与规则分别版本化；恢复历史和按新规则重算分开，重放不应重复发通知或扣费。既有“授予学位”事实不会因新规则计算不通过而自动消失。'],pages=[(39,'当前状态与操作历史：将依赖与历史变成可表示的对象。'),(40,'官方讲义：事件历史生成状态的流程图。'),(41,'讲义补充｜课堂未完整展开：历史恢复、新规则重算、版本与外部副作用。')])
add('结尾：CQRS、DDD 与回到第一性原理',5810.14,[
'讲师在结尾提到 CQRS（Command Query Responsibility Segregation）与 DDD（Domain-Driven Design），并明确 CQRS 与 Event Sourcing 是独立的选择。课堂没有逐项讲授这些方法的完整实现。',
'本课收束到一个问题：面对五十万行教务系统，先跳出当前代码，找到复杂性的来源，再选择能承接变化的表示。即使未听过这些术语，也可以从事实、依赖和时间的需求推导出合理设计。',
'本页及下方补充保留官方现行讲义结尾扩展内容，并明确区分口述。CQRS 分离接受操作的写模型与提供查询的读模型；DDD 让业务概念与限界上下文决定边界；Event Sourcing 决定如何记录和重建历史。三者可组合，却互不等同。'],pages=[(42,'讲义补充｜CQRS：写端维护资格、容量等约束，读端按使用者组织信息。'),(43,'讲义补充｜DDD：统一语言与限界上下文，不同业务对“学生”的模型可以不同。'),(44,'讲义补充｜结论携带输入/规则/审批依据；区分事件生效与系统获知的时间。'),(45,'讲义补充｜并发不变量与模块边界，事件追加不自动解决超卖。'),(46,'讲义补充｜逐步迁移、基线快照、新旧对账与丢失历史的诚实边界。')])
notes=dict(schema_version=2,title='第06课｜需求和架构（1）：让变化有地方可去',source_url='https://www.bilibili.com/video/BV1Rch76WEfQ',limitations=['复用 BaoCut fresh 原始转写，完整阅读19个分块、486条合并原句，保留完整96分50秒课程的时间导航；未逐秒听审。','原视频章节标记“引言（后半音频翻车）”；该段转写存在不流畅和术语错识，连续时间戳不证明音频质量。未凭讲义伪造口述补段。','官方现行 slides6.html 共47页及 lect6.md 完整阅读；其内容比课堂口述更丰富，新增细节均标讲义补充，未验证网页是否为录课当日版本。','讲义图来自官方网页完整页截图汇编，不是同秒视频帧；真实视频帧保留实际秒数。图片可点击放大。','桌面与窄屏浏览器质量复核由课程协调者补记；真实手机未实测。'],read_chunks=[f'chunk-{i:04d}' for i in range(1,20)],omitted=[],summary=['AI 降低了写代码的成本，但需求、产品与架构决定代码朝哪里增长，以及下一次修改要付出多少代价。','真实教务系统、非递归汉诺塔、Excel 二维码和事件溯源共同说明：选择表示方式，就是为复杂性与变化安排位置。','本课特别保留需求调研→只凭规格实现原型的现场链条，以及“缺课次数”的校验争议、课程替代、组织改名和历史重放的边界。'],sections=sections,self_test=[{'question':'为什么 MVP 成功不能证明长期架构合适？','answer':'MVP 只走通最重要路径，尚未经历规则变化、例外、历史数据与真实责任；先前决策会持续约束后续实现。','section':10},{'question':'汉诺塔的三种好表示把复杂性放在哪里？','answer':'数学规律放在不变量和证明；任务栈放在待执行任务分解；抽象机器放在栈帧、程序计数器和小步状态转移。','section':12},{'question':'二维码两个后端结果一致就能证明正确吗？','answer':'不能。二者可能共享算法错误；还需独立实现或解码器。像素比较前须固定编码参数。','section':14},{'question':'为什么只保存 can_graduate=true 不够？','answer':'它可能压缩了成绩、方案版本、课程替代与人工批准，失去决定依据后难以解释历史与定位受影响审核。','section':17},{'question':'事件溯源是不是让新需求不用写逻辑？','answer':'不是。它保留可重建的历史，新业务仍需逻辑、版本语义和并发处理；重放还需隔离外部副作用。','section':19}],supplements=[{'title':'官方讲义扩展：把追溯落到业务数据里','text':'一次毕业审核可记录输入 ID 和版本或快照、规则版本、结论及审批依据。成绩更正后沿依赖找到受影响的审核，正式决定进入复核流程。事件表只是材料，结果对输入的关系仍须明确建模。','source_label':'官方现行讲义补充，课堂未逐项展开','source_url':'https://jyywiki.cn/GSE/2026/slides6.html','pages':[41,44]},{'title':'官方讲义扩展：一致性、时间与逐步迁移','text':'最后一个名额不能被两位学生同时占用，容量检查与占位要在一致性边界内完成；异步课表视图可以稍后刷新，但应向用户说明。豁免6月1日生效、6月3日录入，两个时间分别回答业务是否有效与系统当时为何拒绝。迁移先从毕业审核等业务链开始，保留旧系统基线，新旧并行对账，丢失历史不伪造成事件。简单信息维护仍可使用CRUD。','source_label':'官方现行讲义补充，课堂未逐项展开','source_url':'https://jyywiki.cn/GSE/2026/slides6.html','pages':[44,45,46]}])
(p/'notes.json').write_text(json.dumps(notes,ensure_ascii=False,indent=2))
